=== MPTokenIssuanceCreate ===
import { ValidationError } from '../../errors'
import { isHex, INTEGER_SANITY_CHECK, isFlagEnabled, hasFlag } from '../utils'
import {
  MAX_MPT_META_BYTE_LENGTH,
  MPT_META_WARNING_HEADER,
  validateMPTokenMetadata,
} from '../utils/mptokenMetadata'

import {
  BaseTransaction,
  GlobalFlagsInterface,
  validateBaseTransaction,
  validateOptionalField,
  isString,
  isNumber,
  isDomainID,
} from './common'
import type { TransactionMetadataBase } from './metadata'

// 2^63 - 1
const MAX_AMT = '9223372036854775807'
export const MAX_TRANSFER_FEE = 50000

/**
 * Transaction Flags for an MPTokenIssuanceCreate Transaction.
 *
 * @category Transaction Flags
 */
export enum MPTokenIssuanceCreateFlags {
  /**
   * If set, indicates that the MPT can be locked both individually and globally.
   * If not set, the MPT cannot be locked in any way.
   */
  tfMPTCanLock = 0x00000002,
  /**
   * If set, indicates that individual holders must be authorized.
   * This enables issuers to limit who can hold their assets.
   */
  tfMPTRequireAuth = 0x00000004,
  /**
   * If set, indicates that individual holders can place their balances into an escrow.
   */
  tfMPTCanEscrow = 0x00000008,
  /**
   * If set, indicates that individual holders can trade their balances
   *  using the XRP Ledger DEX or AMM.
   */
  tfMPTCanTrade = 0x00000010,
  /**
   * If set, indicates that tokens may be transferred to other accounts
   *  that are not the issuer.
   */
  tfMPTCanTransfer = 0x00000020,
  /**
   * If set, indicates that the issuer may use the Clawback transaction
   * to clawback value from individual holders.
   */
  tfMPTCanClawback = 0x00000040,
  /**
   * If set, indicates that holders may hold confidential (encrypted) balances
   * of this token and use the Confidential MPT transactions.
   */
  tfMPTCanHoldConfidentialBalance = 0x00000080,
}

/**
 * ImmutableFlags for an MPTokenIssuanceCreate transaction (XLS-94D DynamicMPT).
 *
 * By default `MPTokenMetadata`, `TransferFee`, and the MPT issuance flags below
 * are mutable via MPTokenIssuanceSet. Setting a bit here permanently makes the
 * corresponding field or flag immutable. These transaction-level `tif*` bits
 * share the same numeric values as the on-ledger `lsif*` bits recorded in
 * {@link MPTokenIssuanceImmutableFlags}.
 *
 * @category Transaction Flags
 */
export enum MPTokenIssuanceCreateImmutableFlags {
  /**
   * Make flag `lsfMPTCanLock` immutable.
   */
  tifMPTCanLock = 0x00000002,
  /**
   * Make flag `lsfMPTRequireAuth` immutable.
   */
  tifMPTRequireAuth = 0x00000004,
  /**
   * Make flag `lsfMPTCanEscrow` immutable.
   */
  tifMPTCanEscrow = 0x00000008,
  /**
   * Make flag `lsfMPTCanTrade` immutable.
   */
  tifMPTCanTrade = 0x00000010,
  /**
   * Make flag `lsfMPTCanTransfer` immutable.
   */
  tifMPTCanTransfer = 0x00000020,
  /**
   * Make flag `lsfMPTCanClawback` immutable.
   */
  tifMPTCanClawback = 0x00000040,
  /**
   * Make flag `lsfMPTCanHoldConfidentialBalance` immutable. (XLS-96 Confidential MPT)
   */
  tifMPTCanHoldConfidentialBalance = 0x00000080,
  /**
   * Make field `MPTokenMetadata` immutable.
   */
  tifMPTMetadata = 0x00010000,
  /**
   * Make field `TransferFee` immutable.
   */
  tifMPTTransferFee = 0x00020000,
}

/* eslint-disable no-bitwise -- Need bitwise operations to replicate rippled behavior */
export const tifMPTokenIssuanceImmutableMask = ~(
  MPTokenIssuanceCreateImmutableFlags.tifMPTCanLock |
  MPTokenIssuanceCreateImmutableFlags.tifMPTRequireAuth |
  MPTokenIssuanceCreateImmutableFlags.tifMPTCanEscrow |
  MPTokenIssuanceCreateImmutableFlags.tifMPTCanTrade |
  MPTokenIssuanceCreateImmutableFlags.tifMPTCanTransfer |
  MPTokenIssuanceCreateImmutableFlags.tifMPTCanClawback |
  MPTokenIssuanceCreateImmutableFlags.tifMPTCanHoldConfidentialBalance |
  MPTokenIssuanceCreateImmutableFlags.tifMPTMetadata |
  MPTokenIssuanceCreateImmutableFlags.tifMPTTransferFee
)
/* eslint-enable no-bitwise */

/**
 * Map of flags to boolean values representing {@link MPTokenIssuanceCreate} transaction
 * flags.
 *
 * @category Transaction Flags
 */
// eslint-disable-next-line max-len -- Disable for interface declaration.
export interface MPTokenIssuanceCreateFlagsInterface extends GlobalFlagsInterface {
  tfMPTCanLock?: boolean
  /**
   * If set, indicates that individual holders must be authorized.
   * This enables issuers to limit who can hold their assets.
   */
  tfMPTRequireAuth?: boolean
  /**
   * If set, indicates that individual holders can place their balances into an escrow.
   */
  tfMPTCanEscrow?: boolean
  /**
   * If set, indicates that individual holders can trade their balances
   *  using the XRP Ledger DEX or AMM.
   */
  tfMPTCanTrade?: boolean
  /**
   * If set, indicates that tokens may be transferred to other accounts
   *  that are not the issuer.
   */
  tfMPTCanTransfer?: boolean
  /**
   * If set, indicates that the issuer may use the Clawback transaction
   * to clawback value from individual holders.
   */
  tfMPTCanClawback?: boolean
  /**
   * If set, indicates that holders may hold confidential (encrypted) balances
   * of this token and use the Confidential MPT transactions.
   */
  tfMPTCanHoldConfidentialBalance?: boolean
}

export interface MPTokenIssuanceCreateImmutableFlagsInterface {
  /**
   * Make flag `lsfMPTCanLock` immutable.
   */
  tifMPTCanLock?: boolean
  /**
   * Make flag `lsfMPTRequireAuth` immutable.
   */
  tifMPTRequireAuth?: boolean
  /**
   * Make flag `lsfMPTCanEscrow` immutable.
   */
  tifMPTCanEscrow?: boolean
  /**
   * Make flag `lsfMPTCanTrade` immutable.
   */
  tifMPTCanTrade?: boolean
  /**
   * Make flag `lsfMPTCanTransfer` immutable.
   */
  tifMPTCanTransfer?: boolean
  /**
   * Make flag `lsfMPTCanClawback` immutable.
   */
  tifMPTCanClawback?: boolean
  /**
   * Make flag `lsfMPTCanHoldConfidentialBalance` immutable. (XLS-96 Confidential MPT)
   */
  tifMPTCanHoldConfidentialBalance?: boolean
  /**
   * Make field `MPTokenMetadata` immutable.
   */
  tifMPTMetadata?: boolean
  /**
   * Make field `TransferFee` immutable.
   */
  tifMPTTransferFee?: boolean
}

/**
 * The MPTokenIssuanceCreate transaction creates a MPTokenIssuance object
 * and adds it to the relevant directory node of the creator account.
 * This transaction is the only opportunity an issuer has to specify any token fields
 * that are defined as immutable (e.g., MPT Flags). If the transaction is successful,
 * the newly created token will be owned by the account (the creator account) which
 * executed the transaction.
 */
export interface MPTokenIssuanceCreate extends BaseTransaction {
  TransactionType: 'MPTokenIssuanceCreate'
  /**
   * An asset scale is the difference, in orders of magnitude, between a standard unit and
   * a corresponding fractional unit. More formally, the asset scale is a non-negative integer
   * (0, 1, 2, …) such that one standard unit equals 10^(-scale) of a corresponding
   * fractional unit. If the fractional unit equals the standard unit, then the asset scale is 0.
   * Note that this value is optional, and will default to 0 if not supplied.
   */
  AssetScale?: number
  /**
   * Specifies the maximum asset amount of this token that should ever be issued.
   * It is a non-negative integer string that can store a range of up to 63 bits. If not set, the max
   * amount will default to the largest unsigned 63-bit integer (0x7FFFFFFFFFFFFFFF or 9223372036854775807)
   *
   * Example:
   * ```
   * MaximumAmount: '9223372036854775807'
   * ```
   */
  MaximumAmount?: string
  /**
   * Specifies the fee to charged by the issuer for secondary sales of the Token,
   * if such sales are allowed. Valid values for this field are between 0 and 50,000 inclusive,
   * allowing transfer rates of between 0.000% and 50.000% in increments of 0.001.
   * The field must NOT be present if the `tfMPTCanTransfer` flag is not set.
   */
  TransferFee?: number

  /**
   * Should follow {@link https://github.com/XRPLF/XRPL-Standards/tree/master/XLS-0089-multi-purpose-token-metadata-schema | XLS-89} standard.
   * Use {@link encodeMPTokenMetadata} utility function to convert to convert {@link MPTokenMetadata} to a blob.
   * Use {@link decodeMPTokenMetadata} utility function to convert from a blob to {@link MPTokenMetadata}.
   *
   * While adherence to the XLS-89d format is not mandatory, non-compliant metadata
   * may not be discoverable by ecosystem tools such as explorers and indexers.
   */
  MPTokenMetadata?: string

  Flags?: number | MPTokenIssuanceCreateFlagsInterface

  /**
   * A bitmask of {@link MPTokenIssuanceCreateImmutableFlags} (`tif*`) that
   * permanently makes the corresponding fields or MPT issuance flags immutable.
   * By default `MPTokenMetadata`, `TransferFee`, and the MPT issuance flags
   * remain mutable via MPTokenIssuanceSet; setting a bit here opts out of that
   * mutability for the life of the issuance. (XLS-94D)
   */
  ImmutableFlags?: number

  /* The domainID that governs admissibility pertaining to the MPToken. */
  DomainID?: string
}

export interface MPTokenIssuanceCreateMetadata extends TransactionMetadataBase {
  mpt_issuance_id?: string
}

/* eslint-disable max-lines-per-function, max-statements -- Not needed to reduce function */
/**
 * Verify the form and type of an MPTokenIssuanceCreate at runtime.
 *
 * @param tx - An MPTokenIssuanceCreate Transaction.
 * @throws When the MPTokenIssuanceCreate is Malformed.
 */
export function validateMPTokenIssuanceCreate(
  tx: Record<string, unknown>,
): void {
  validateBaseTransaction(tx)
  validateOptionalField(tx, 'MaximumAmount', isString)
  validateOptionalField(tx, 'MPTokenMetadata', isString)
  validateOptionalField(tx, 'TransferFee', isNumber)
  validateOptionalField(tx, 'AssetScale', isNumber)
  validateOptionalField(tx, 'ImmutableFlags', isNumber)
  validateOptionalField(tx, 'DomainID', isDomainID)

  if (
    tx.DomainID != null &&
    !hasFlag(
      tx,
      MPTokenIssuanceCreateFlags.tfMPTRequireAuth,
      'tfMPTRequireAuth',
    )
  ) {
    throw new ValidationError(
      'MPTokenIssuanceCreate: Cannot set DomainID unless tfMPTRequireAuth flag is set.',
    )
  }

  if (typeof tx.ImmutableFlags === 'number') {
    // eslint-disable-next-line no-bitwise -- Need bitwise operations to replicate rippled behavior
    const invalidBits = tx.ImmutableFlags & tifMPTokenIssuanceImmutableMask
    // rippled rejects a present-but-zero ImmutableFlags, as well as out-of-mask bits.
    if (tx.ImmutableFlags === 0 || invalidBits !== 0) {
      throw new ValidationError(
        'MPTokenIssuanceCreate: Invalid ImmutableFlags value',
      )
    }
  }

  if (
    typeof tx.MPTokenMetadata === 'string' &&
    (!isHex(tx.MPTokenMetadata) ||
      tx.MPTokenMetadata.length / 2 > MAX_MPT_META_BYTE_LENGTH)
  ) {
    throw new ValidationError(
      `MPTokenIssuanceCreate: MPTokenMetadata (hex format) must be non-empty and no more than ${MAX_MPT_META_BYTE_LENGTH} bytes.`,
    )
  }

  if (typeof tx.MaximumAmount === 'string') {
    if (!INTEGER_SANITY_CHECK.exec(tx.MaximumAmount)) {
      throw new ValidationError('MPTokenIssuanceCreate: Invalid MaximumAmount')
    } else if (
      BigInt(tx.MaximumAmount) > BigInt(MAX_AMT) ||
      BigInt(tx.MaximumAmount) <= BigInt(`0`)
    ) {
      throw new ValidationError(
        'MPTokenIssuanceCreate: MaximumAmount out of range',
      )
    }
  }

  if (typeof tx.TransferFee === 'number') {
    // eslint-disable-next-line @typescript-eslint/consistent-type-assertions -- Not necessary
    const flags = (tx.Flags ?? 0) as
      | number
      | MPTokenIssuanceCreateFlagsInterface
    const isTfMPTCanTransfer =
      typeof flags === 'number'
        ? isFlagEnabled(flags, MPTokenIssuanceCreateFlags.tfMPTCanTransfer)
        : (flags.tfMPTCanTransfer ?? false)
    const isTfMPTCanHoldConfidentialBalance =
      typeof flags === 'number'
        ? isFlagEnabled(
            flags,
            MPTokenIssuanceCreateFlags.tfMPTCanHoldConfidentialBalance,
          )
        : (flags.tfMPTCanHoldConfidentialBalance ?? false)

    if (tx.TransferFee < 0 || tx.TransferFee > MAX_TRANSFER_FEE) {
      throw new ValidationError(
        `MPTokenIssuanceCreate: TransferFee must be between 0 and ${MAX_TRANSFER_FEE}`,
      )
    }

    if (tx.TransferFee && !isTfMPTCanTransfer) {
      throw new ValidationError(
        'MPTokenIssuanceCreate: TransferFee cannot be provided without enabling tfMPTCanTransfer flag',
      )
    }

    // Confidential amounts are encrypted, so a transfer rate cannot be applied
    // to them; rippled rejects this pairing with temBAD_TRANSFER_FEE.
    if (tx.TransferFee && isTfMPTCanHoldConfidentialBalance) {
      throw new ValidationError(
        'MPTokenIssuanceCreate: TransferFee cannot be provided together with the tfMPTCanHoldConfidentialBalance flag',
      )
    }
  }

  if (tx.MPTokenMetadata != null) {
    const validationMessages = validateMPTokenMetadata(tx.MPTokenMetadata)

    if (validationMessages.length > 0) {
      const message = [
        MPT_META_WARNING_HEADER,
        ...validationMessages.map((msg) => `- ${msg}`),
      ].join('\n')

      // eslint-disable-next-line no-console -- Required here.
      console.warn(message)
    }
  }
}
/* eslint-enable max-lines-per-function, max-statements */
=== MPTokenAuthorize ===
import {
  BaseTransaction,
  isString,
  validateBaseTransaction,
  validateRequiredField,
  Account,
  validateOptionalField,
  isAccount,
  GlobalFlagsInterface,
} from './common'

/**
 * Transaction Flags for an MPTokenAuthorize Transaction.
 *
 * @category Transaction Flags
 */
export enum MPTokenAuthorizeFlags {
  /**
   * If set and transaction is submitted by a holder, it indicates that the holder no
   * longer wants to hold the MPToken, which will be deleted as a result. If the the holder's
   * MPToken has non-zero balance while trying to set this flag, the transaction will fail. On
   * the other hand, if set and transaction is submitted by an issuer, it would mean that the
   * issuer wants to unauthorize the holder (only applicable for allow-listing),
   * which would unset the lsfMPTAuthorized flag on the MPToken.
   */
  tfMPTUnauthorize = 0x00000001,
}

/**
 * Map of flags to boolean values representing {@link MPTokenAuthorize} transaction
 * flags.
 *
 * @category Transaction Flags
 */
export interface MPTokenAuthorizeFlagsInterface extends GlobalFlagsInterface {
  tfMPTUnauthorize?: boolean
}

/**
 * The MPTokenAuthorize transaction is used to globally lock/unlock a MPTokenIssuance,
 * or lock/unlock an individual's MPToken.
 */
export interface MPTokenAuthorize extends BaseTransaction {
  TransactionType: 'MPTokenAuthorize'
  /**
   * Identifies the MPTokenIssuance
   */
  MPTokenIssuanceID: string
  /**
   * An optional XRPL Address of an individual token holder balance to lock/unlock.
   * If omitted, this transaction will apply to all any accounts holding MPTs.
   */
  Holder?: Account
  Flags?: number | MPTokenAuthorizeFlagsInterface
}

/**
 * Verify the form and type of an MPTokenAuthorize at runtime.
 *
 * @param tx - An MPTokenAuthorize Transaction.
 * @throws When the MPTokenAuthorize is Malformed.
 */
export function validateMPTokenAuthorize(tx: Record<string, unknown>): void {
  validateBaseTransaction(tx)
  validateRequiredField(tx, 'MPTokenIssuanceID', isString)
  validateOptionalField(tx, 'Holder', isAccount)
}
=== MPTokenIssuanceSet ===
import { ValidationError } from '../../errors'
import { isFlagEnabled, isHex } from '../utils'
// eslint-disable-next-line import/no-cycle -- this method is needed to convert txn flags to number
import { convertTxFlagsToNumber } from '../utils/flags'
import {
  MAX_MPT_META_BYTE_LENGTH,
  MPT_META_WARNING_HEADER,
  validateMPTokenMetadata,
} from '../utils/mptokenMetadata'

import {
  BaseTransaction,
  isString,
  validateBaseTransaction,
  validateRequiredField,
  Account,
  validateOptionalField,
  isAccount,
  GlobalFlagsInterface,
  isNumber,
  isDomainID,
  isHexWithByteLength,
  CONFIDENTIAL_EC_POINT_BYTES,
} from './common'
import {
  MAX_TRANSFER_FEE,
  tifMPTokenIssuanceImmutableMask,
} from './MPTokenIssuanceCreate'

import type { Transaction } from '.'

/**
 * Transaction Flags for an MPTokenIssuanceSet Transaction.
 *
 * @category Transaction Flags
 */
export enum MPTokenIssuanceSetFlags {
  /**
   * If set, indicates that issuer locks the MPT
   */
  tfMPTLock = 0x00000001,
  /**
   * If set, indicates that issuer unlocks the MPT
   */
  tfMPTUnlock = 0x00000002,
  /**
   * Sets the `lsfMPTCanLock` flag. Enables the token to be locked both individually and globally. (XLS-94D)
   */
  tfMPTSetCanLock = 0x00000004,
  /**
   * Sets the `lsfMPTRequireAuth` flag. Requires individual holders to be authorized. (XLS-94D)
   */
  tfMPTSetRequireAuth = 0x00000008,
  /**
   * Sets the `lsfMPTCanEscrow` flag. Allows holders to place balances into escrow. (XLS-94D)
   */
  tfMPTSetCanEscrow = 0x00000010,
  /**
   * Sets the `lsfMPTCanTrade` flag. Allows holders to trade balances on the XRPL DEX. (XLS-94D)
   */
  tfMPTSetCanTrade = 0x00000020,
  /**
   * Sets the `lsfMPTCanTransfer` flag. Allows tokens to be transferred to non-issuer accounts. (XLS-94D)
   */
  tfMPTSetCanTransfer = 0x00000040,
  /**
   * Sets the `lsfMPTCanClawback` flag. Enables the issuer to claw back tokens
   * via `Clawback` or `AMMClawback` transactions. (XLS-94D)
   */
  tfMPTSetCanClawback = 0x00000080,
  /**
   * Sets the `lsfMPTCanHoldConfidentialBalance` flag. Enables the token to be held
   * in a confidential balance. (XLS-96 Confidential MPT)
   */
  tfMPTSetCanHoldConfidentialBalance = 0x00000100,
}

/* eslint-disable no-bitwise -- Need bitwise operations to replicate rippled behavior */
/**
 * The set of capability-setting `tfMPTSet*` flags. These one-way flags enable
 * the corresponding capability on the MPTokenIssuance ledger object; once
 * enabled, a capability cannot be disabled via a subsequent MPTokenIssuanceSet.
 */
export const tfMPTokenIssuanceSetEnableFlagMask =
  MPTokenIssuanceSetFlags.tfMPTSetCanLock |
  MPTokenIssuanceSetFlags.tfMPTSetRequireAuth |
  MPTokenIssuanceSetFlags.tfMPTSetCanEscrow |
  MPTokenIssuanceSetFlags.tfMPTSetCanTrade |
  MPTokenIssuanceSetFlags.tfMPTSetCanTransfer |
  MPTokenIssuanceSetFlags.tfMPTSetCanClawback |
  MPTokenIssuanceSetFlags.tfMPTSetCanHoldConfidentialBalance
/* eslint-enable no-bitwise */

/**
 * Map of flags to boolean values representing {@link MPTokenIssuanceSet} transaction
 * flags.
 *
 * @category Transaction Flags
 */
export interface MPTokenIssuanceSetFlagsInterface extends GlobalFlagsInterface {
  tfMPTLock?: boolean
  tfMPTUnlock?: boolean
  /* Sets the `lsfMPTCanLock` flag. Enables the token to be locked both individually and globally. */
  tfMPTSetCanLock?: boolean
  /* Sets the `lsfMPTRequireAuth` flag. Requires individual holders to be authorized. */
  tfMPTSetRequireAuth?: boolean
  /* Sets the `lsfMPTCanEscrow` flag. Allows holders to place balances into escrow. */
  tfMPTSetCanEscrow?: boolean
  /* Sets the `lsfMPTCanTrade` flag. Allows holders to trade balances on the XRPL DEX. */
  tfMPTSetCanTrade?: boolean
  /* Sets the `lsfMPTCanTransfer` flag. Allows tokens to be transferred to non-issuer accounts. */
  tfMPTSetCanTransfer?: boolean
  /**
   * Sets the `lsfMPTCanClawback` flag. Enables the issuer to claw back tokens
   * via `Clawback` or `AMMClawback` transactions.
   */
  tfMPTSetCanClawback?: boolean
  /**
   * Sets the `lsfMPTCanHoldConfidentialBalance` flag. Enables the token to be
   * held in a confidential balance. (XLS-96 Confidential MPT)
   */
  tfMPTSetCanHoldConfidentialBalance?: boolean
}

/**
 * The MPTokenIssuanceSet transaction is used to globally lock/unlock a MPTokenIssuance,
 * or lock/unlock an individual's MPToken.
 */
export interface MPTokenIssuanceSet extends BaseTransaction {
  TransactionType: 'MPTokenIssuanceSet'
  /**
   * Identifies the MPTokenIssuance
   */
  MPTokenIssuanceID: string
  /**
   * An optional XRPL Address of an individual token holder balance to lock/unlock.
   * If omitted, this transaction will apply to all any accounts holding MPTs.
   */
  Holder?: Account
  /**
   * The issuer's compressed ElGamal encryption key (33-byte EC point),
   * registered so confidential amounts can be encrypted to the issuer.
   */
  IssuerEncryptionKey?: string
  /**
   * The auditor's compressed ElGamal encryption key (33-byte EC point),
   * registered so confidential amounts can be encrypted to an auditor.
   */
  AuditorEncryptionKey?: string
  Flags?: number | MPTokenIssuanceSetFlagsInterface

  /**
   * New metadata to replace the existing value, in hex format (max 1024 bytes).
   * The transaction will be rejected if `lsifMPTMetadata` has been set in
   * `ImmutableFlags`. Setting an empty `MPTokenMetadata` removes the field.
   * Should follow the
   * {@link https://github.com/XRPLF/XRPL-Standards/tree/master/XLS-0089-multi-purpose-token-metadata-schema | XLS-89} standard.
   */
  MPTokenMetadata?: string
  /**
   * New transfer fee value, between 0 and 50,000 inclusive (in increments of
   * 0.001%). The transaction will be rejected if `lsifMPTTransferFee` has been
   * set in `ImmutableFlags`. A non-zero value requires `lsfMPTCanTransfer` to
   * already be set on the ledger, or to be enabled by this same transaction via
   * `tfMPTSetCanTransfer`. Setting `TransferFee` to zero removes the field.
   */
  TransferFee?: number
  /**
   * Declares which fields or flags are immutable, via a bitmask of
   * {@link MPTokenIssuanceCreateImmutableFlags} (`tif*`). Once a bit is set, the
   * corresponding field or flag can never be set or modified again. The
   * `ImmutableFlags` provided here are added to the current ledger object's
   * `ImmutableFlags`; it is not a complete replacement. (XLS-94D)
   */
  ImmutableFlags?: number
  /**
   * The PermissionedDomain object ID that gates who may hold this MPT. Cannot
   * be set together with the `Holder` field.
   */
  DomainID?: string
}

/* eslint-disable max-lines-per-function, max-statements -- All validation rules are needed */
/**
 * Verify the form and type of an MPTokenIssuanceSet at runtime.
 *
 * @param tx - An MPTokenIssuanceSet Transaction.
 * @throws When the MPTokenIssuanceSet is Malformed.
 */
export function validateMPTokenIssuanceSet(tx: Record<string, unknown>): void {
  validateBaseTransaction(tx)
  validateRequiredField(tx, 'MPTokenIssuanceID', isString)
  validateOptionalField(tx, 'Holder', isAccount)
  validateOptionalField(
    tx,
    'IssuerEncryptionKey',
    isHexWithByteLength(CONFIDENTIAL_EC_POINT_BYTES),
  )
  validateOptionalField(
    tx,
    'AuditorEncryptionKey',
    isHexWithByteLength(CONFIDENTIAL_EC_POINT_BYTES),
  )
  if (tx.AuditorEncryptionKey != null && tx.IssuerEncryptionKey == null) {
    throw new ValidationError(
      'MPTokenIssuanceSet: AuditorEncryptionKey requires IssuerEncryptionKey',
    )
  }
  validateOptionalField(tx, 'MPTokenMetadata', isString)
  validateOptionalField(tx, 'TransferFee', isNumber)
  validateOptionalField(tx, 'ImmutableFlags', isNumber)
  validateOptionalField(tx, 'DomainID', isDomainID)

  if (tx.DomainID != null && tx.Holder != null) {
    throw new ValidationError(
      'MPTokenIssuanceSet: Cannot set both DomainID and Holder fields.',
    )
  }

  if (typeof tx.ImmutableFlags === 'number') {
    // eslint-disable-next-line no-bitwise -- Need bitwise operations to replicate rippled behavior
    const invalidBits = tx.ImmutableFlags & tifMPTokenIssuanceImmutableMask
    // rippled rejects a present-but-zero ImmutableFlags, as well as out-of-mask bits.
    if (tx.ImmutableFlags === 0 || invalidBits !== 0) {
      throw new ValidationError(
        'MPTokenIssuanceSet: Invalid ImmutableFlags value',
      )
    }
  }

  // eslint-disable-next-line @typescript-eslint/consistent-type-assertions -- Pseudo-Txn missing in BaseTransaction type.
  const flagsNum = convertTxFlagsToNumber(tx as Transaction)
  const isTfMPTLock = isFlagEnabled(flagsNum, MPTokenIssuanceSetFlags.tfMPTLock)
  const isTfMPTUnlock = isFlagEnabled(
    flagsNum,
    MPTokenIssuanceSetFlags.tfMPTUnlock,
  )
  // eslint-disable-next-line no-bitwise -- Need bitwise operations to replicate rippled behavior
  const hasEnableFlag = (flagsNum & tfMPTokenIssuanceSetEnableFlagMask) !== 0

  if (isTfMPTLock && isTfMPTUnlock) {
    throw new ValidationError('MPTokenIssuanceSet: flag conflict')
  }

  if (tx.Holder != null && tx.Holder === tx.Account) {
    throw new ValidationError(
      'MPTokenIssuanceSet: Holder cannot be the same as the Account.',
    )
  }

  // A mutation sets/updates a capability flag, MPTokenMetadata, TransferFee, or
  // ImmutableFlags. These may not be combined with a Holder or a lock/unlock.
  const isMutate =
    hasEnableFlag ||
    tx.MPTokenMetadata != null ||
    tx.TransferFee != null ||
    tx.ImmutableFlags != null
  const isSetConfidentialKeys =
    tx.IssuerEncryptionKey != null || tx.AuditorEncryptionKey != null

  if (
    flagsNum === 0 &&
    tx.DomainID == null &&
    !isMutate &&
    !isSetConfidentialKeys
  ) {
    throw new ValidationError(
      'MPTokenIssuanceSet: Transaction does not change the state of the MPTokenIssuance ledger object.',
    )
  }

  if (isMutate && tx.Holder != null) {
    throw new ValidationError(
      'MPTokenIssuanceSet: Holder field is not allowed when mutating MPTokenIssuance.',
    )
  }

  // Registering issuer/auditor encryption keys is issuance-wide; rippled rejects it
  // paired with a per-holder target (temMALFORMED).
  if (isSetConfidentialKeys && tx.Holder != null) {
    throw new ValidationError(
      'MPTokenIssuanceSet: Holder field is not allowed when registering confidential encryption keys.',
    )
  }

  if (isMutate && (isTfMPTLock || isTfMPTUnlock)) {
    throw new ValidationError(
      'MPTokenIssuanceSet: Can not lock/unlock while mutating MPTokenIssuance.',
    )
  }

  if (typeof tx.TransferFee === 'number') {
    if (tx.TransferFee < 0 || tx.TransferFee > MAX_TRANSFER_FEE) {
      throw new ValidationError(
        `MPTokenIssuanceSet: TransferFee must be between 0 and ${MAX_TRANSFER_FEE}`,
      )
    }
    // Confidential amounts are encrypted, so a transfer rate cannot apply;
    // rippled rejects this pairing with temBAD_TRANSFER_FEE.
    if (
      tx.TransferFee > 0 &&
      isFlagEnabled(
        flagsNum,
        MPTokenIssuanceSetFlags.tfMPTSetCanHoldConfidentialBalance,
      )
    ) {
      throw new ValidationError(
        'MPTokenIssuanceSet: TransferFee cannot be provided together with the tfMPTSetCanHoldConfidentialBalance flag',
      )
    }
  }

  // An empty MPTokenMetadata is valid on MPTokenIssuanceSet: per rippled it
  // clears the existing metadata (makeFieldAbsent). Only validate the hex
  // format, length, and XLS-89 schema when a non-empty value is supplied.
  if (typeof tx.MPTokenMetadata === 'string' && tx.MPTokenMetadata.length > 0) {
    if (
      !isHex(tx.MPTokenMetadata) ||
      tx.MPTokenMetadata.length / 2 > MAX_MPT_META_BYTE_LENGTH
    ) {
      throw new ValidationError(
        `MPTokenIssuanceSet: MPTokenMetadata must be a valid hex string no more than ${MAX_MPT_META_BYTE_LENGTH} bytes (an empty string clears the field).`,
      )
    }

    const validationMessages = validateMPTokenMetadata(tx.MPTokenMetadata)

    if (validationMessages.length > 0) {
      const message = [
        MPT_META_WARNING_HEADER,
        ...validationMessages.map((msg) => `- ${msg}`),
      ].join('\n')

      // eslint-disable-next-line no-console -- Required here.
      console.warn(message)
    }
  }
}
