const xrpl = require('xrpl');
(async () => {
  const client = new xrpl.Client('wss://s.altnet.rippletest.net:51233');
  await client.connect();
  const issuer = xrpl.Wallet.fromSeed('<TESTNET_SEED_REDACTED>');
  const { wallet: holder } = await client.fundWallet();
  console.log('holder', holder.address);

  async function submit(wallet, tx) {
    const r = await client.submitAndWait(tx, { wallet });
    const code = r.result.meta && typeof r.result.meta !== 'string' ? r.result.meta.TransactionResult : undefined;
    console.log(tx.TransactionType, '->', code);
    return r;
  }

  const create = await submit(issuer, {
    TransactionType: 'MPTokenIssuanceCreate',
    Account: issuer.address,
    Flags: 0x00000002 | 0x00000004 | 0x00000040 | 0x00000020, // CanLock, RequireAuth, CanClawback, CanTransfer
  });
  const issuanceId = create.result.meta.mpt_issuance_id;
  console.log('issuanceId', issuanceId);

  await submit(holder, { TransactionType: 'MPTokenAuthorize', Account: holder.address, MPTokenIssuanceID: issuanceId });
  await submit(issuer, { TransactionType: 'MPTokenAuthorize', Account: issuer.address, MPTokenIssuanceID: issuanceId, Holder: holder.address });
  await submit(issuer, { TransactionType: 'Payment', Account: issuer.address, Destination: holder.address, Amount: { mpt_issuance_id: issuanceId, value: '100' } });

  // Lock the holder
  await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.address, MPTokenIssuanceID: issuanceId, Holder: holder.address, Flags: 0x00000001 });

  console.log('--- while locked ---');
  await submit(holder, { TransactionType: 'Payment', Account: holder.address, Destination: issuer.address, Amount: { mpt_issuance_id: issuanceId, value: '1' } });
  await submit(issuer, { TransactionType: 'Payment', Account: issuer.address, Destination: holder.address, Amount: { mpt_issuance_id: issuanceId, value: '1' } });

  await client.disconnect();
})().catch(e => { console.error(e); process.exit(1); });
EOF
