const xrpl = require('xrpl');
(async () => {
  const client = new xrpl.Client('wss://s.altnet.rippletest.net:51233');
  await client.connect();
  const issuer = xrpl.Wallet.fromSeed('<TESTNET_SEED_REDACTED>');
  const { wallet: h1 } = await client.fundWallet();
  const { wallet: h2 } = await client.fundWallet();
  console.log('h1', h1.address, 'h2', h2.address);

  async function submit(wallet, tx) {
    const r = await client.submitAndWait(tx, { wallet });
    const code = r.result.meta && typeof r.result.meta !== 'string' ? r.result.meta.TransactionResult : undefined;
    console.log(tx.TransactionType, tx.Holder ? `(holder ${tx.Holder})` : '', '->', code);
    return r;
  }

  const create = await submit(issuer, {
    TransactionType: 'MPTokenIssuanceCreate',
    Account: issuer.address,
    Flags: 0x00000002 | 0x00000004 | 0x00000040 | 0x00000020,
  });
  const issuanceId = create.result.meta.mpt_issuance_id;
  console.log('issuanceId', issuanceId);

  for (const h of [h1, h2]) {
    await submit(h, { TransactionType: 'MPTokenAuthorize', Account: h.address, MPTokenIssuanceID: issuanceId });
    await submit(issuer, { TransactionType: 'MPTokenAuthorize', Account: issuer.address, MPTokenIssuanceID: issuanceId, Holder: h.address });
    await submit(issuer, { TransactionType: 'Payment', Account: issuer.address, Destination: h.address, Amount: { mpt_issuance_id: issuanceId, value: '100' } });
  }

  console.log('--- lock h1 individually ---');
  await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.address, MPTokenIssuanceID: issuanceId, Holder: h1.address, Flags: 0x00000001 });

  console.log('--- h1 (locked) -> h2 (unlocked) transfer ---');
  await submit(h1, { TransactionType: 'Payment', Account: h1.address, Destination: h2.address, Amount: { mpt_issuance_id: issuanceId, value: '1' } });

  console.log('--- h2 (unlocked) -> h1 (locked) transfer ---');
  await submit(h2, { TransactionType: 'Payment', Account: h2.address, Destination: h1.address, Amount: { mpt_issuance_id: issuanceId, value: '1' } });

  console.log('--- unlock h1 ---');
  await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.address, MPTokenIssuanceID: issuanceId, Holder: h1.address, Flags: 0x00000002 });

  console.log('--- global lock ---');
  await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.address, MPTokenIssuanceID: issuanceId, Flags: 0x00000001 });

  console.log('--- h1 -> h2 transfer while globally locked ---');
  await submit(h1, { TransactionType: 'Payment', Account: h1.address, Destination: h2.address, Amount: { mpt_issuance_id: issuanceId, value: '1' } });

  console.log('--- global unlock ---');
  await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.address, MPTokenIssuanceID: issuanceId, Flags: 0x00000002 });

  await client.disconnect();
})().catch(e => { console.error(e); process.exit(1); });

